CHAR16 *
SplitStr (
    CHAR16 **List,
       CHAR16 Separator
  )
{
  CHAR16  *Str;
  CHAR16  *ReturnStr;
  Str = *List;
  ReturnStr = Str;
  if (IS_NULL (*Str)) {
    return ReturnStr;
  }
  while (!IS_NULL (*Str)) {
    if (*Str != Separator) {
      break;
    }
    Str++;
  }
  if (*Str == Separator) {
    *Str = L'\0';
    Str++;
  }
  *List = Str;
  return ReturnStr;
}

