code:
UAVTalkRxState UAVTalkProcessInputStreamQuiet(UAVTalkConnection connectionHandle, uint8_t rxbyte)
{
	UAVTalkConnectionData *connection;
	CHECKCONHANDLE(connectionHandle,connection,return -1);
	UAVTalkInputProcessor *iproc = &connection->iproc;
	++connection->stats.rxBytes;
	if (iproc->state == UAVTALK_STATE_ERROR) {
		connection->stats.rxErrors++;
		iproc->state = UAVTALK_STATE_SYNC;
	} else if (iproc->state == UAVTALK_STATE_COMPLETE) {
		iproc->state = UAVTALK_STATE_SYNC;
	}
	if (iproc->rxPacketLength < 0xffff)
		iproc->rxPacketLength++;   
	switch (iproc->state)
	{
	case UAVTALK_STATE_SYNC:
		if (rxbyte != UAVTALK_SYNC_VAL)
			break;
		iproc->cs = PIOS_CRC_updateByte(0, rxbyte);
		iproc->rxPacketLength = 1;
		iproc->state = UAVTALK_STATE_TYPE;
		break;
	case UAVTALK_STATE_TYPE:
		iproc->cs = PIOS_CRC_updateByte(iproc->cs, rxbyte);
		if ((rxbyte & UAVTALK_TYPE_MASK) != UAVTALK_TYPE_VER) {
			iproc->state = UAVTALK_STATE_ERROR;
			break;
		}
		iproc->type = rxbyte;
		iproc->packet_size = 0;
		iproc->state = UAVTALK_STATE_SIZE;
		iproc->rxCount = 0;
		break;
	case UAVTALK_STATE_SIZE:
		iproc->cs = PIOS_CRC_updateByte(iproc->cs, rxbyte);
		if (iproc->rxCount == 0) {
			iproc->packet_size += rxbyte;
			iproc->rxCount++;
			break;
		}
		iproc->packet_size += rxbyte << 8;
		if (iproc->packet_size < UAVTALK_MIN_HEADER_LENGTH ||
				iproc->packet_size > UAVTALK_MAX_HEADER_LENGTH + UAVTALK_MAX_PAYLOAD_LENGTH) { 
			iproc->state = UAVTALK_STATE_ERROR;
			break;
		}
		iproc->rxCount = 0;
		iproc->objId = 0;
		iproc->state = UAVTALK_STATE_OBJID;
		break;
	case UAVTALK_STATE_OBJID:
		iproc->cs = PIOS_CRC_updateByte(iproc->cs, rxbyte);
		iproc->objId += rxbyte << (8*(iproc->rxCount++));
		if (iproc->rxCount < 4)
			break;
		if (iproc->type == UAVTALK_TYPE_FILEREQ) {
			iproc->instanceLength = 0;
			iproc->rxCount = 0;
			iproc->length = 6;
			if ((iproc->packet_size - iproc->rxPacketLength) !=
					iproc->length) {
				iproc->state = UAVTALK_STATE_ERROR;
				break;
			}
			iproc->state = UAVTALK_STATE_DATA;
			break;
		}
		iproc->obj = UAVObjGetByID(iproc->objId);
		if (iproc->type == UAVTALK_TYPE_OBJ_REQ || iproc->type == UAVTALK_TYPE_ACK || iproc->type == UAVTALK_TYPE_NACK) {
			iproc->length = 0;
			iproc->instanceLength = 0;
			if ((iproc->packet_size - iproc->rxPacketLength) == 2) {
				iproc->instanceLength = 2;
			} else if (iproc->length > 0) {
				iproc->state = UAVTALK_STATE_ERROR;
				break; 
			}
		} else {
			if (iproc->obj) {
				iproc->length = UAVObjGetNumBytes(iproc->obj);
				iproc->instanceLength = (UAVObjIsSingleInstance(iproc->obj) ? 0 : 2);
			} else {
				iproc->instanceLength = 0;
				iproc->length = iproc->packet_size - iproc->rxPacketLength;
			}
		}
		if (iproc->length >= UAVTALK_MAX_PAYLOAD_LENGTH) {
			iproc->state = UAVTALK_STATE_ERROR;
			break;
		}
		if ((iproc->rxPacketLength + iproc->instanceLength + iproc->length) != iproc->packet_size) { 
			if (iproc->instanceLength == 0) {
				iproc->instanceLength = 2;
			}
		}
		if ((iproc->rxPacketLength + iproc->instanceLength + iproc->length) != iproc->packet_size) { 
			iproc->state = UAVTALK_STATE_ERROR;
			break;
		}
		iproc->instId = 0;
		if (iproc->type == UAVTALK_TYPE_NACK) {
			iproc->state = UAVTALK_STATE_CS;
		}
		else if (iproc->instanceLength) {
			iproc->state = UAVTALK_STATE_INSTID;
		} else {
			if (iproc->length > 0)
				iproc->state = UAVTALK_STATE_DATA;
			else
				iproc->state = UAVTALK_STATE_CS;
		}
		iproc->rxCount = 0;
		break;
	case UAVTALK_STATE_INSTID:
		iproc->cs = PIOS_CRC_updateByte(iproc->cs, rxbyte);
		iproc->instId += rxbyte << (8*(iproc->rxCount++));
		if (iproc->rxCount < 2)
			break;
		iproc->rxCount = 0;
		if (iproc->length > 0)
			iproc->state = UAVTALK_STATE_DATA;
		else
			iproc->state = UAVTALK_STATE_CS;
		break;
	case UAVTALK_STATE_DATA:
		iproc->cs = PIOS_CRC_updateByte(iproc->cs, rxbyte);
		connection->rxBuffer[iproc->rxCount++] = rxbyte;
		if (iproc->rxCount < iproc->length)
			break;
		iproc->state = UAVTALK_STATE_CS;
		iproc->rxCount = 0;
		break;
	case UAVTALK_STATE_CS:
		if (rxbyte != iproc->cs) { 
			connection->stats.rxCRC++;
			iproc->state = UAVTALK_STATE_ERROR;
			break;
		}
		if (iproc->rxPacketLength != (iproc->packet_size + 1)) { 
			iproc->state = UAVTALK_STATE_ERROR;
			break;
		}
		connection->stats.rxObjectBytes += iproc->length;
		connection->stats.rxObjects++;
		iproc->state = UAVTALK_STATE_COMPLETE;
		break;
	default:
		iproc->state = UAVTALK_STATE_ERROR;
	}
	return iproc->state;
}

