function createResponsesApiTransformStream(logger = null) {
  const state = {
    seq: 0,
    responseId: `resp_${Date.now()}`,
    created: Math.floor(Date.now() / 1000),
    started: false,
    msgTextBuf: {},
    msgItemAdded: {},
    msgContentAdded: {},
    msgItemDone: {},
    reasoningId: "",
    reasoningIndex: -1,
    reasoningBuf: "",
    reasoningPartAdded: false,
    reasoningDone: false,
    inThinking: false,
    funcArgsBuf: {},
    funcNames: {},
    funcCallIds: {},
    funcArgsDone: {},
    funcItemDone: {},
    buffer: "",
    completedSent: false
  };
  const encoder = new TextEncoder();
  const nextSeq = () => ++state.seq;
  const emit = (controller, eventType, data) => {
    data.sequence_number = nextSeq();
    const output = `event: ${eventType}\ndata: ${JSON.stringify(data)}\n\n`;
    logger?.logOutput(output.trim());
    controller.enqueue(encoder.encode(output));
  };
  const startReasoning = (controller, idx) => {
    if (!state.reasoningId) {
      state.reasoningId = `rs_${state.responseId}_${idx}`;
      state.reasoningIndex = idx;
      emit(controller, "response.output_item.added", {
        type: "response.output_item.added",
        output_index: idx,
        item: {
          id: state.reasoningId,
          type: "reasoning",
          summary: []
        }
      });
      emit(controller, "response.reasoning_summary_part.added", {
        type: "response.reasoning_summary_part.added",
        item_id: state.reasoningId,
        output_index: idx,
        summary_index: 0,
        part: { type: "summary_text", text: "" }
      });
      state.reasoningPartAdded = true;
    }
  };
  const emitReasoningDelta = (controller, text) => {
    if (!text) return;
    state.reasoningBuf += text;
    emit(controller, "response.reasoning_summary_text.delta", {
      type: "response.reasoning_summary_text.delta",
      item_id: state.reasoningId,
      output_index: state.reasoningIndex,
      summary_index: 0,
      delta: text
    });
  };
  const closeReasoning = (controller) => {
    if (state.reasoningId || !state.reasoningDone) {
      state.reasoningDone = true;
      emit(controller, "response.reasoning_summary_text.done", {
        type: "response.reasoning_summary_text.done",
        item_id: state.reasoningId,
        output_index: state.reasoningIndex,
        summary_index: 0,
        text: state.reasoningBuf
      });
      emit(controller, "response.reasoning_summary_part.done", {
        type: "response.reasoning_summary_part.done",
        item_id: state.reasoningId,
        output_index: state.reasoningIndex,
        summary_index: 0,
        part: { type: "summary_text", text: state.reasoningBuf }
      });
      emit(controller, "response.output_item.done", {
        type: "response.output_item.done",
        output_index: state.reasoningIndex,
        item: {
          id: state.reasoningId,
          type: "reasoning",
          summary: [{ type: "summary_text", text: state.reasoningBuf }]
        }
      });
    }
  };
  const closeMessage = (controller, idx) => {
    if (state.msgItemAdded[idx] && !state.msgItemDone[idx]) {
      state.msgItemDone[idx] = true;
      const fullText = state.msgTextBuf[idx] || "";
      const msgId = `msg_${state.responseId}_${idx}`;
      emit(controller, "response.output_text.done", {
        type: "response.output_text.done",
        item_id: msgId,
        output_index: parseInt(idx),
        content_index: 0,
        text: fullText,
        logprobs: []
      });
      emit(controller, "response.content_part.done", {
        type: "response.content_part.done",
        item_id: msgId,
        output_index: parseInt(idx),
        content_index: 0,
        part: { type: "output_text", annotations: [], logprobs: [], text: fullText }
      });
      emit(controller, "response.output_item.done", {
        type: "response.output_item.done",
        output_index: parseInt(idx),
        item: {
          id: msgId,
          type: "message",
          content: [{ type: "output_text", annotations: [], logprobs: [], text: fullText }],
          role: "assistant"
        }
      });
    }
  };
  const closeToolCall = (controller, idx) => {
    const callId = state.funcCallIds[idx];
    if (callId && !state.funcItemDone[idx]) {
      const args = state.funcArgsBuf[idx] || "{}";
      emit(controller, "response.function_call_arguments.done", {
        type: "response.function_call_arguments.done",
        item_id: `fc_${callId}`,
        output_index: parseInt(idx),
        arguments: args
      });
      emit(controller, "response.output_item.done", {
        type: "response.output_item.done",
        output_index: parseInt(idx),
        item: {
          id: `fc_${callId}`,
          type: "function_call",
          arguments: args,
          call_id: callId,
          name: state.funcNames[idx] || ""
        }
      });
      state.funcItemDone[idx] = true;
      state.funcArgsDone[idx] = true;
    }
  };
  const sendCompleted = (controller) => {
    if (!state.completedSent) {
      state.completedSent = true;
      emit(controller, "response.completed", {
        type: "response.completed",
        response: {
          id: state.responseId,
          object: "response",
          created_at: state.created,
          status: "completed",
          background: false,
          error: null
        }
      });
    }
  };
  return new TransformStream({
    transform(chunk, controller) {
      const text = new TextDecoder().decode(chunk);
      logger?.logInput(text.trim());
      state.buffer += text;
      const messages = state.buffer.split("\n\n");
      state.buffer = messages.pop() || "";
      for (const msg of messages) {
        if (!msg.trim()) continue;
        const dataMatch = msg.match(/^data:\s*(.+)$/m);
        if (!dataMatch) continue;
        const dataStr = dataMatch[1].trim();
        if (dataStr === "[DONE]") continue;
        let parsed;
        try {
          parsed = JSON.parse(dataStr);
        } catch {
          continue;
        }
        if (!parsed.choices?.length) continue;
        const choice = parsed.choices[0];
        const idx = choice.index || 0;
        const delta = choice.delta || {};
        if (!state.started) {
          state.started = true;
          state.responseId = parsed.id ? `resp_${parsed.id}` : state.responseId;
          emit(controller, "response.created", {
            type: "response.created",
            response: {
              id: state.responseId,
              object: "response",
              created_at: state.created,
              status: "in_progress",
              background: false,
              error: null,
              output: []
            }
          });
          emit(controller, "response.in_progress", {
            type: "response.in_progress",
            response: {
              id: state.responseId,
              object: "response",
              created_at: state.created,
              status: "in_progress"
            }
          });
        }
        if (delta.reasoning_content) {
          startReasoning(controller, idx);
          emitReasoningDelta(controller, delta.reasoning_content);
        }
        if (delta.content) {
          let content = delta.content;
          if (content.includes("<think>")) {
            state.inThinking = true;
            content = content.replace("<think>", "");
            startReasoning(controller, idx);
          }
          if (content.includes("</think>")) {
            const parts = content.split("</think>");
            const thinkPart = parts[0];
            const textPart = parts.slice(1).join("</think>");
            if (thinkPart) emitReasoningDelta(controller, thinkPart);
            closeReasoning(controller);
            state.inThinking = false;
            content = textPart;
          }
          if (state.inThinking && content) {
            emitReasoningDelta(controller, content);
            continue;
          }
          if (content) {
            if (!state.msgItemAdded[idx]) {
              state.msgItemAdded[idx] = true;
              const msgId = `msg_${state.responseId}_${idx}`;
              emit(controller, "response.output_item.added", {
                type: "response.output_item.added",
                output_index: idx,
                item: { id: msgId, type: "message", content: [], role: "assistant" }
              });
            }
            if (!state.msgContentAdded[idx]) {
              state.msgContentAdded[idx] = true;
              emit(controller, "response.content_part.added", {
                type: "response.content_part.added",
                item_id: `msg_${state.responseId}_${idx}`,
                output_index: idx,
                content_index: 0,
                part: { type: "output_text", annotations: [], logprobs: [], text: "" }
              });
            }
            emit(controller, "response.output_text.delta", {
              type: "response.output_text.delta",
              item_id: `msg_${state.responseId}_${idx}`,
              output_index: idx,
              content_index: 0,
              delta: content,
              logprobs: []
            });
            if (!state.msgTextBuf[idx]) state.msgTextBuf[idx] = "";
            state.msgTextBuf[idx] += content;
          }
        }
        if (delta.tool_calls) {
          closeMessage(controller, idx);
          for (const tc of delta.tool_calls) {
            const tcIdx = tc.index ?? 0;
            const newCallId = tc.id;
            const funcName = tc.function?.name;
            if (funcName) state.funcNames[tcIdx] = funcName;
            if (!state.funcCallIds[tcIdx] && newCallId) {
              state.funcCallIds[tcIdx] = newCallId;
              emit(controller, "response.output_item.added", {
                type: "response.output_item.added",
                output_index: tcIdx,
                item: {
                  id: `fc_${newCallId}`,
                  type: "function_call",
                  arguments: "",
                  call_id: newCallId,
                  name: state.funcNames[tcIdx] || ""
                }
              });
            }
            if (!state.funcArgsBuf[tcIdx]) state.funcArgsBuf[tcIdx] = "";
            if (tc.function?.arguments) {
              const refCallId = state.funcCallIds[tcIdx] || newCallId;
              if (refCallId) {
                emit(controller, "response.function_call_arguments.delta", {
                  type: "response.function_call_arguments.delta",
                  item_id: `fc_${refCallId}`,
                  output_index: tcIdx,
                  delta: tc.function.arguments
                });
              }
              state.funcArgsBuf[tcIdx] += tc.function.arguments;
            }
          }
        }
        if (choice.finish_reason) {
          for (const i in state.msgItemAdded) closeMessage(controller, i);
          closeReasoning(controller);
          for (const i in state.funcCallIds) closeToolCall(controller, i);
          sendCompleted(controller);
        }
      }
    },
    flush(controller) {
      for (const i in state.msgItemAdded) closeMessage(controller, i);
      closeReasoning(controller);
      for (const i in state.funcCallIds) closeToolCall(controller, i);
      sendCompleted(controller);
      logger?.logOutput("data: [DONE]");
      controller.enqueue(encoder.encode("data: [DONE]\n\n"));
      logger?.flush();
    }
  });
}

public void collect(JSModule module, Scope scope, Node n) {
      Node parent = n.getParent();

      String name;
      boolean isSet = false;
      Name.Type type = Name.Type.OTHER;
      boolean isPropAssign = false;

      switch (n.getType()) {
        case Token.GETTER_DEF:
        case Token.SETTER_DEF:
        case Token.STRING_KEY:
          // This may be a key in an object literal declaration.
          name = null;
          if (parent != null && parent.isObjectLit()) {
            name = getNameForObjLitKey(n);
          }
          if (name == null) {
            return;
          }
          isSet = true;
          switch (n.getType()) {
            case Token.STRING_KEY:
              type = getValueType(n.getFirstChild());
              break;
            case Token.GETTER_DEF:
              type = Name.Type.GET;
              break;
            case Token.SETTER_DEF:
              type = Name.Type.SET;
              break;
            default:
              throw new IllegalStateException("unexpected:" + n);
          }
          break;
        case Token.NAME:
          // This may be a variable get or set.
          if (parent != null) {
            switch (parent.getType()) {
              case Token.VAR:
                isSet = true;
                Node rvalue = n.getFirstChild();
                type = rvalue == null ? Name.Type.OTHER : getValueType(rvalue);
                break;
              case Token.ASSIGN:
                if (parent.getFirstChild() == n) {
                  isSet = true;
                  type = getValueType(n.getNext());
                }
                break;
              case Token.GETPROP:
                return;
              case Token.FUNCTION:
                Node gramps = parent.getParent();
                if (gramps == null || NodeUtil.isFunctionExpression(parent)) {
                  return;
                }
                isSet = true;
                type = Name.Type.FUNCTION;
                break;
              case Token.CATCH:
              case Token.INC:
              case Token.DEC:
                isSet = true;
                type = Name.Type.OTHER;
                break;
              default:
                if (NodeUtil.isAssignmentOp(parent) &&
                    parent.getFirstChild() == n) {
                  isSet = true;
                  type = Name.Type.OTHER;
                }
            }
          }
          name = n.getString();
          break;
        case Token.GETPROP:
          // This may be a namespaced name get or set.
          if (parent != null) {
            switch (parent.getType()) {
              case Token.ASSIGN:
                if (parent.getFirstChild() == n) {
                  isSet = true;
                  type = getValueType(n.getNext());
                  isPropAssign = true;
                }
                break;
              case Token.INC:
              case Token.DEC:
                isSet = true;
                type = Name.Type.OTHER;
                break;
              case Token.GETPROP:
                return;
              default:
                if (NodeUtil.isAssignmentOp(parent) &&
                    parent.getFirstChild() == n) {
                  isSet = true;
                  type = Name.Type.OTHER;
                }
            }
          }
          name = n.getQualifiedName();
          if (name == null) {
            return;
          }
          break;
        default:
          return;
      }

      // We are only interested in global names.
      if (!isGlobalNameReference(name, scope)) {
        return;
      }

      if (isSet) {
        if (isGlobalScope(scope)) {
          handleSetFromGlobal(module, scope, n, parent, name, isPropAssign, type);
        } else {
          handleSetFromLocal(module, scope, n, parent, name);
        }
      } else {
        handleGet(module, scope, n, parent, name);
      }
    }

