    pool->cur = (yyjson_mut_val *)(void *)((u8 *)chunk) + 1;
    pool->end = (yyjson_mut_val *)(void *)((u8 *)chunk + size);
    size = yyjson_min(pool->chunk_size * 2, pool->chunk_size_max);
