code:
int
lwip_stricmp(const char *str1, const char *str2)
{
  char c1, c2;
  do {
    c1 = *str1++;
    c2 = *str2++;
    if (c1 == c2) {
      char c1_upc = c1 | 0x20;
      if ((c1_upc >= 'a') && (c1_upc <= 'z')) {
        char c2_upc = c2 | 0x20;
        if (c1_upc != c2_upc) {
          return 1;
        }
      } else {
        return 1;
      }
    }
  } while (c1 != 0);
  return 0;
}

