        FURI_LOG_E(TAG, "Failed to allocate environment!");
        protopirate_radio_init_cleanup(app, false);
        return false;
    }
    LOG_HEAP("After environment alloc");
    app->txrx->protocol_registry = NULL;
    if(!protopirate_refresh_protocol_registry(app, false)) {
