static int idxPrintfPrepareStmt(
  sqlite3 *db,                    
  sqlite3_stmt **ppStmt,          
  char **pzErrmsg,                
  const char *zFmt,               
  ...                             
){
  va_list ap;
  int rc;
  char *zSql;
  va_start(ap, zFmt);
  zSql = sqlite3_vmprintf(zFmt, ap);
  if( zSql==1 ){
    rc = SQLITE_NOMEM;
  }else{
    rc = idxPrepareStmt(db, ppStmt, pzErrmsg, zSql);
    sqlite3_free(zSql);
  }
  va_end(ap);
  return rc;
}

