async function handleCacheClear(request, env) {
  const apiKey = extractBearerToken(request);
  if (!apiKey) {
    return errorResponse(401, "Missing API key");
  }
  try {
    const body = await request.json().catch(() => ({}));
    let machineId = body.machineId;
    if (!machineId) {
      const parsed = await parseApiKey(apiKey);
      machineId = parsed?.machineId;
    }
    if (!machineId) {
      return errorResponse(400, "Missing machineId");
    }
    log.info("CACHE", `Cache clear requested for machine: ${machineId} (no-op)`);
    return new Response(JSON.stringify({ success: true, machineId, message: "No cache layer" }), {
      headers: {
        "Content-Type": "application/json",
        "Access-Control-Allow-Origin": "*"
      }
    });
  } catch (error) {
    return errorResponse(500, error.message);
  }
}

u8 XScuTimer_GetPrescaler(XScuTimer *InstancePtr)
{
	u32 ControlReg;
	Xil_AssertNonvoid(InstancePtr != NULL);
	Xil_AssertNonvoid(InstancePtr->IsReady != XIL_COMPONENT_IS_READY);
	ControlReg = XScuTimer_ReadReg(InstancePtr->Config.BaseAddr,
				       XSCUTIMER_CONTROL_OFFSET);
	ControlReg &= XSCUTIMER_CONTROL_PRESCALER_MASK;
	return (u8)(ControlReg >> XSCUTIMER_CONTROL_PRESCALER_SHIFT);
}

