double js_sqrt(double x)
{
	double z;
	int 	sign = (int)0x80000000; 
	unsigned r,t1,s1,ix1,q1;
	int ix0,s0,q,m,t,i;
	EXTRACT_WORDS(ix0, ix1, x);
	if((ix0&0x7ff00000)==0x7ff00000) {			
	    return x*x+x;		
	} 
	if(ix0<=0) {
	    if(((ix0&(~sign))|ix1)==0) return x;
	    else if(ix0<0)
		return (x-x)/(x-x);		
	}
	m = (ix0>>20);
	if(m==0) {				
	    while(ix0==0) {
		m -= 21;
		ix0 |= (ix1>>11); ix1 <<= 21;
	    }
	    for(i=0;(ix0&0x00100000)==0;i++) ix0<<=1;
	    m -= i-1;
	    ix0 |= (ix1>>(32-i));
	    ix1 <<= i;
	}
	m -= 1023;	
	ix0 = (ix0&0x000fffff)|0x00100000;
	if(m&1){	
	    ix0 += ix0 + ((ix1&sign)>>31);
	    ix1 += ix1;
	}
	m >>= 1;	
	ix0 += ix0 + ((ix1&sign)>>31);
	ix1 += ix1;
	q = q1 = s0 = s1 = 0;	
	r = 0x00200000;		
	while(r!=0) {
	    t = s0+r; 
	    if(t<=ix0) { 
		s0   = t+r; 
		ix0 -= t; 
		q   += r; 
	    } 
	    ix0 += ix0 + ((ix1&sign)>>31);
	    ix1 += ix1;
	    r>>=1;
	}
	r = sign;
	while(r!=0) {
	    t1 = s1+r; 
	    t  = s0;
	    if((t<ix0)||((t==ix0)&&(t1<=ix1))) { 
		s1  = t1+r;
		if(((t1&sign)==sign)&&(s1&sign)==0) s0 += 1;
		ix0 -= t;
		if (ix1 < t1) ix0 -= 1;
		ix1 -= t1;
		q1  += r;
	    }
	    ix0 += ix0 + ((ix1&sign)>>31);
	    ix1 += ix1;
	    r>>=1;
	}
	if((ix0|ix1)!=0) {
	    z = one-tiny; 
	    if (z>=one) {
	        z = one+tiny;
	        if (q1==(unsigned)0xffffffff) { q1=0; q += 1;}
		else if (z>one) {
		    if (q1==(unsigned)0xfffffffe) q+=1;
		    q1+=2; 
		} else
	            q1 += (q1&1);
	    }
	}
	ix0 = (q>>1)+0x3fe00000;
	ix1 =  q1>>1;
	if ((q&1)==1) ix1 |= sign;
	ix0 += (m <<20);
	return float64_from_u32(ix0, ix1);
}

void s5BAudioClockTimers()
{
	if((s5b_apu.ctr&0xF) == 0)
	{
		uint8_t i;
		for(i = 0; i < 3; i++)
		{
			if(s5b_apu.freqCtr[i])
				s5b_apu.freqCtr[i]--;
			if(s5b_apu.freqCtr[i] == 0)
			{
				s5b_apu.freqCtr[i] = s5b_apu.freq[i];
				s5b_apu.cycle[i]++;
			}
		}
		if(s5b_apu.noiseFreqCtr)
			s5b_apu.noiseFreqCtr--;
		if(s5b_apu.noiseFreqCtr == 0)
		{
			s5b_apu.noiseFreqCtr = s5b_apu.noiseFreq;
			if(s5b_apu.noiseReg&1) s5b_apu.noiseReg ^= 0x24000;
			s5b_apu.noiseReg >>= 1;
		}
		if(s5b_apu.envFreqCtr)
			s5b_apu.envFreqCtr--;
		if(s5b_apu.envFreqCtr == 0)
		{
			s5b_apu.envFreqCtr = s5b_apu.envFreq;
			if(s5b_apu.envStep >= 63)
			{
				if(s5b_apu.envRepeat)
					s5b_apu.envStep = 0;
			}
			else
				s5b_apu.envStep++;
			s5b_apu.envVol = s5b_apu.volTbl[s5b_apu.envShapeTbl[s5b_apu.envShape][s5b_apu.envStep]];
		}
	}
	s5b_apu.ctr++;
}

