static void set_processed_input(BOOL enable)
{
    DWORD mode;
    HANDLE handle;
    handle = (HANDLE)_get_osfhandle(1);
    if (!GetConsoleMode(handle, &mode))
        return;
    if (enable)
        mode |= ENABLE_PROCESSED_INPUT;
    else
        mode &= ~ENABLE_PROCESSED_INPUT;
    SetConsoleMode(handle, mode);
}

