function shouldFilterActor(actor) {
    const title = (actor.title || actor.name || '').toLowerCase();
    const name = (actor.name || '').toLowerCase();
    const filterPatterns = [
        /^my actor/i,           
        /^testactor/i,          
        /^test crawler/i,       
        /^test actor/i,         
        /^my actorrr/i,         
        /^my actor\s*\d+$/i,   
        /^test\s*$/i,          
        /^test\s+crawler/i,    
    ];
    for (const pattern of filterPatterns) {
        if (pattern.test(title) || pattern.test(name)) {
            return true;
        }
    }
    const description = (actor.description || '').toLowerCase().trim();
    if (description === 'test' || description === '') {
        if (title.includes('my actor') || title.includes('test')) {
            return true;
        }
    }
    return false;
}

static uint32_t ComputeDistanceShortcut(const size_t block_start,
                                        const size_t pos,
                                        const size_t max_backward,
                                        const size_t gap,
                                        const ZopfliNode* nodes) {
  const size_t clen = ZopfliNodeCopyLength(&nodes[pos]);
  const size_t ilen = nodes[pos].dcode_insert_length & 0x7FFFFFF;
  const size_t dist = ZopfliNodeCopyDistance(&nodes[pos]);
  if (pos == 0) {
    return 0;
  } else if (dist + clen <= block_start + pos + gap &&
             dist <= max_backward + gap &&
             ZopfliNodeDistanceCode(&nodes[pos]) > 0) {
    return (uint32_t)pos;
  } else {
    return nodes[pos - clen - ilen].u.shortcut;
  }
}

