double js_acos(double x)
{
	double z,r,w,s,c,df;
	int hx,ix;
	hx = get_high_word(x);
	ix = hx&0x7fffffff;
	if(ix>=0x3ff00000) {	
	    if(((ix-0x3ff00000)|get_low_word(x))==0) {	
		if(hx>0) return 0.0;		
		else return pi+2.0*pio2_lo;	
	    }
	    return (x-x)/(x-x);		
	}
	if(ix<0x3fe00000) {	
	    if(ix<=0x3c600000) return pio2_hi+pio2_lo;
	    z = x*x;
            r = R(z);
	    return pio2_hi - (x - (pio2_lo-x*r));
	} else  {
	    z = (one-fabs(x))*0.5;
            r = R(z);
	    s = js_sqrt(z);
            if (hx<0) {		
                w = r*s-pio2_lo;
                return pi - 2.0*(s+w);
            } else {			
                df = zero_low(s);
                c  = (z-df*df)/(s+df);
                w = r*s+c;
                return 2.0*(df+w);
            }
        }
}

