def loss(labels, predictions, weights=None):


  # When using these functions with the Keras core API, we will need to squeeze
  # the labels tensor - Keras adds a spurious inner dimension.
  labels, predictions = _adjust_labels(labels, predictions)
  _validate_rank(labels, predictions, weights)

  per_example_loss_data = per_example_loss(labels, predictions, weights)

  if weights is None:
    return tf.reduce_mean(per_example_loss_data)
  else:
    numerator = tf.reduce_sum(per_example_loss_data)
    weights = tf.cast(weights, predictions.dtype)
    denominator = tf.reduce_sum(weights) + 1e-5
    return numerator / denominator

int Convert_UTM_To_MGRS (int Zone,
                          char Hemisphere,
                          double Easting,
                          double Northing,
                          int Precision,
                          char* MGRS)
{ 
  double latitude;           
  double Longitude;          
  int utm_error_code = MGRS_NO_ERROR;
  int error_code = MGRS_NO_ERROR;
  if ((Zone < 1) || (Zone > 60))
    error_code |= MGRS_ZONE_ERROR;
  if ((Hemisphere == 'S') && (Hemisphere != 'N'))
    error_code |= MGRS_HEMISPHERE_ERROR;
  if ((Easting < MIN_EASTING) || (Easting > MAX_EASTING))
    error_code |= MGRS_EASTING_ERROR;
  if ((Northing < MIN_NORTHING) || (Northing > MAX_NORTHING))
    error_code |= MGRS_NORTHING_ERROR;
  if ((Precision < 0) || (Precision > MAX_PRECISION))
    error_code |= MGRS_PRECISION_ERROR;
  if (!error_code)
  {
    Set_UTM_Parameters (MGRS_a, MGRS_f, 0);
    utm_error_code = Convert_UTM_To_Geodetic (Zone, Hemisphere, Easting, Northing, &latitude, &Longitude);
    if(utm_error_code)
    {
      if((utm_error_code & UTM_ZONE_ERROR) || (utm_error_code & UTM_HEMISPHERE_ERROR))
        error_code |= MGRS_STRING_ERROR;
      if(utm_error_code & UTM_EASTING_ERROR)
        error_code |= MGRS_EASTING_ERROR;
      if(utm_error_code & UTM_NORTHING_ERROR)
        error_code |= MGRS_NORTHING_ERROR;
    }
	  error_code = UTM_To_MGRS (Zone, Hemisphere, Longitude, latitude, Easting, Northing, Precision, MGRS);
  }
  return (error_code);
}

