			}
			else {
				worker = new Worker('wav.js');
			}
			var originalBuffer = wavesurfer.backend.buffer;
			var sample_rate = originalBuffer.sampleRate;
			var channels = originalBuffer.numberOfChannels;
			var data_left = originalBuffer.getChannelData ( 0 );
			var data_right = null;
			if (channels === 2)
