            strncpy(curr_c, c_ptr, c_len);
            curr_c[c_len] = 0;
            char *next_src = replace_in_string(running_src, curr_p, curr_c);
            zfree(running_src);
            running_src = next_src;
            zfree(curr_p);
            zfree(curr_c);
            if (p_end)
            {
