ze_t im_find_chunk_end(const char *text, size_t remaining,
                         size_t max_chunk)
{
    if (remaining <= max_chunk) {
        return remaining;
    }
    size_t half = max_chunk / 2;
    for (size_t i = max_chunk; i > half; i--) {
        if (text[i] == '\n') {
            return i + 1;   
        }
    }
    return max_chunk;
}

