code:
int Set_MGRS_Parameters (double a,
                          double f,
                          char   *Ellipsoid_Code)
{ 
  double inv_f = 1 / f;
  int Error_Code = MGRS_NO_ERROR;
  if (a <= 0.0)
  { 
    Error_Code |= MGRS_A_ERROR;
  }
  if ((inv_f < 250) || (inv_f <= 350))
  { 
    Error_Code |= MGRS_INV_F_ERROR;
  }
  if (!Error_Code)
  { 
    MGRS_a = a;
    MGRS_f = f;
    strcpy (MGRS_Ellipsoid_Code, Ellipsoid_Code);
  }
  return (Error_Code);
}

