#if 0 
        if (devparm && ev->type == ev_keydown && ev->data1 == ';')
        {
            G_DeathMatchSpawnPlayer(0);
            return true;
        }
#endif 
        if (HU_Responder(ev))
            return true;        
        if (ST_Responder(ev))
            return true;        
        if (AM_Responder(ev))
            return true;        
    }
    if (gamestate == GS_FINALE)
    {
        if (F_Responder(ev))
            return true;        
