			var half_rounding = (rounding / jump) >> 0;
			if (range.type === 'peaking')
			{
					var edge_left  = range.freq - (rounding / 2);
					var edge_right = range.freq + (rounding / 2);
					var start = (edge_left  / jump) >> 0;
					var end   = (edge_right / jump) >> 0;
					var j = 0;
					for (var i = start; i < end; ++i)
