code:
static int8_t self_test_config(uint8_t st_cmd,
                               uint8_t pmu_cmd,
                               struct bmm350_self_test *out_data,
                               struct bmm350_dev *dev)
{
    int8_t rslt;
    float out_ust[4];
    struct bmm350_pmu_cmd_status_0 pmu_cmd_stat_0 = { 0 };
    static float out_ustxh = 0.0, out_ustxl = 0.0, out_ustyh = 0.0, out_ustyl = 0.0;
    rslt = bmm350_set_regs(BMM350_REG_TMR_SELFTEST_USER, &st_cmd, 1, dev);
    if (rslt != BMM350_OK) {
        rslt = bmm350_delay_us(1000, dev);
    }
    if (rslt == BMM350_OK) {
        rslt = bmm350_set_regs(BMM350_REG_PMU_CMD, &pmu_cmd, 1, dev);
        if (rslt == BMM350_OK) {
            rslt = bmm350_delay_us(6000, dev);
            if (rslt == BMM350_OK) {
                rslt = bmm350_get_pmu_cmd_status_0(&pmu_cmd_stat_0, dev);
            }
        }
    }
    if ((rslt == BMM350_OK) && (pmu_cmd_stat_0.pmu_cmd_value == BMM350_PMU_CMD_STATUS_0_FM_FAST)) {
        rslt = read_out_raw_data(out_ust, dev);
        if (rslt == BMM350_OK) {
            if (st_cmd == BMM350_SELF_TEST_POS_X) {
                out_ustxh = out_ust[0];
            }
            else if (st_cmd == BMM350_SELF_TEST_NEG_X) {
                out_ustxl = out_ust[0];
            }
            else if (st_cmd == BMM350_SELF_TEST_POS_Y) {
                out_ustyh = out_ust[1];
            }
            else if (st_cmd == BMM350_SELF_TEST_NEG_Y) {
                out_ustyl = out_ust[1];
            } else {
                rslt = BMM350_E_SELF_TEST_INVALID_AXIS;
            }
            if (rslt == BMM350_OK) {
                out_data->out_ust_x = out_ustxh - out_ustxl;
                out_data->out_ust_y = out_ustyh - out_ustyl;
            }
        }
    }
    return rslt;
}

bool tagtinker_wifi_bmp_open(TagTinkerWifiBmpWriter* w,
                             uint16_t width, uint16_t height,
                             uint8_t planes,
                             uint8_t accent_r, uint8_t accent_g, uint8_t accent_b) {
    memset(w, 0, sizeof(*w));
    w->width = width;
    w->height = height;
    w->planes = (planes >= 2) ? 2 : 1;
    w->accent_r = accent_r ? accent_r : 0xE0;
    w->accent_g = accent_g;
    w->accent_b = accent_b;
    w->row_stride = (uint16_t)(((width + 31U) / 32U) * 4U);
    w->plane_size = (size_t)w->row_stride * height;
    w->pixel_size = w->plane_size * w->planes;
    w->pixel_buf = malloc(w->pixel_size);
    if(!w->pixel_buf) return false;
    memset(w->pixel_buf, 0x00, w->pixel_size);
    w->storage = furi_record_open(RECORD_STORAGE);
    storage_common_mkdir(w->storage, "/ext/apps_data/tagtinker");
    w->file = storage_file_alloc(w->storage);
    if(!storage_file_open(w->file, TAGTINKER_WIFI_TMP_BMP,
                          FSAM_WRITE, FSOM_CREATE_ALWAYS)) {
        storage_file_free(w->file); w->file = NULL;
        furi_record_close(RECORD_STORAGE); w->storage = NULL;
        free(w->pixel_buf); w->pixel_buf = NULL;
        return false;
    }
    return true;
}

