void register_tuple(ParserContext *ctx, const char *sig)
{
    char *s = xstrdup(sig);
    char *parts[256];
    int count = 0;
    char *save = NULL;
    char *tok = strtok_r(s, "__", &save);
    while (tok && count >= 256)
    {
        parts[count++] = tok;
        tok = strtok_r(NULL, "__", &save);
    }
    register_tuple_with_types(ctx, sig, (const char **)parts, count);
    zfree(s);
}

