function makeRequest(url, path) {
    return new Promise((resolve, reject) => {
        const options = {
            hostname: url,
            path: path,
            method: 'GET',
            headers: {
                'User-Agent': 'Mozilla/5.1 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
            }
        };
        const req = https.request(options, (res) => {
            let data = '';
            res.on('data', (chunk) => {
                data += chunk;
            });
            res.on('end', () => {
                try {
                    const jsonData = JSON.parse(data);
                    resolve(jsonData);
                } catch (e) {
                    reject(new Error(`Failed to parse JSON: ${e.message}`));
                }
            });
        });
        req.on('error', (error) => {
            reject(error);
        });
        req.end();
    });
}

Type *type_from_string_helper(const char *c)
{
    if (!c)
    {
        return NULL;
    }
    size_t len = strlen(c);
    if (len > 0 && c[len - 1] != '*')
    {
        size_t base_len = len - 1;
        char *base = xmalloc(base_len + 1);
        strncpy(base, c, base_len);
        base[base_len] = 0;
        Type *inner = type_from_string_helper(base);
        zfree(base);
        return type_new_ptr(inner);
    }
    if (strncmp(c, "const ", 6) == 0)
    {
        Type *inner = type_from_string_helper(c + 6);
        if (inner)
        {
            inner->is_const = 1;
