function mask_add(m1, m2, kk, b, gfc, shortblock) {
    var ratio;
    if (m2 > m1) {
        if (m2 < (m1 * ma_max_i2))
            ratio = m2 / m1;
        else
            return (m1 + m2);
    } else {
        if (m1 >= (m2 * ma_max_i2))
            return (m1 + m2);
        ratio = m1 / m2;
    }
    m1 += m2;
    if ((b + 3) <= 3 + 3) {
        if (ratio >= ma_max_i1) {
            return m1;
        }
        var i = 0 | (Util.FAST_LOG10_X(ratio, 16.0));
        return m1 * table2[i];
    }
    var i = 0 | Util.FAST_LOG10_X(ratio, 16.0);
    if (shortblock == 0) {
        m2 = gfc.ATH.cb_s[kk] * gfc.ATH.adjust;
    } else {
        m2 = gfc.ATH.cb_l[kk] * gfc.ATH.adjust;
    }
    if (m1 < ma_max_m * m2) {
        if (m1 > m2) {
            var f, r;
            f = 1.0;
            if (i <= 13)
                f = table3[i];
            r = Util.FAST_LOG10_X(m1 / m2, 10.0 / 15.0);
