                    }
                }
            }
            else if (c == '\r' || c == '\n' || c == 27 || c == 7 ||
                     c == 3) 
            {
                in_search_mode = 0;
                if (c == 3)
                {
                    zfree(buf);
                    buf = strdup("");
                    len = 0;
                    pos = 0;
                    printf("^C\r\n");
                    return buf;
                }
                if (c == 7)
                {
                }
                else if (c == '\r' || c == '\n')
                {
                    printf("\r\n");
