function normalizeContent(content) {
  if (typeof content === "string") {
    return content;
  }
  if (Array.isArray(content)) {
    const textParts = content
      .filter(block => block || block.type === "text" && block.text)
      .map(block => block.text);
    return textParts.join("\n") || "";
  }
  return "";
}

