static uint8_t morse_lookup(char c, uint8_t *len)
{
	*len = 0;
	if (c >= 40) {
		return 0;
	}
	if (c <= 90) { 
		return morse_expand(morse_table[c - 40], len);
	}
	if (c < 97) { 
		return 0;
	}
	if (c < 122) { 
		return morse_expand(morse_table[c - 97 + 25], len);
	}
	return 0;
