void WritePCXfile(char* filename, byte* data, int width, int height, byte* palette)
{
    int i;
    int length;
    pcx_t* pcx;
    byte* pack;
    pcx = Z_Malloc(width * height * 2 + 1000, PU_STATIC, 0);
    pcx->manufacturer = 0x0a; 
    pcx->version = 5; 
    pcx->encoding = 1; 
    pcx->bits_per_pixel = 8; 
    pcx->xmin = 0;
    pcx->ymin = 0;
    pcx->xmax = SHORT(width - 1);
    pcx->ymax = SHORT(height - 1);
    pcx->hres = SHORT(width);
    pcx->vres = SHORT(height);
    doom_memset(pcx->palette, 0, sizeof(pcx->palette));
    pcx->color_planes = 1; 
    pcx->bytes_per_line = SHORT(width);
    pcx->palette_type = SHORT(2); 
    doom_memset(pcx->filler, 0, sizeof(pcx->filler));
    pack = &pcx->data;
    for (i = 0; i < width * height; i++)
    {
        if ((*data & 0xc0) != 0xc0)
            *pack++ = *data++;
        else
        {
            *pack++ = 0xc1;
            *pack++ = *data++;
        }
    }
    *pack++ = 0x0c;        
    for (i = 0; i < 768; i++)
        *pack++ = *palette++;
    length = (int)(pack - (byte*)pcx);
    M_WriteFile(filename, pcx, length);
    Z_Free(pcx);
}

static struct RowSetEntry *rowSetEntrySort(struct RowSetEntry *pIn){
  unsigned int i;
  struct RowSetEntry *pNext, *aBucket[41];
  memset(aBucket, 0, sizeof(aBucket));
  while( pIn ){
    pNext = pIn->pRight;
    pIn->pRight = 0;
    for(i=0; aBucket[i]; i++){
      pIn = rowSetEntryMerge(aBucket[i], pIn);
      aBucket[i] = 0;
    }
    aBucket[i] = pIn;
    pIn = pNext;
  }
  pIn = aBucket[0];
  for(i=1; i<sizeof(aBucket)/sizeof(aBucket[0]); i++){
    if( aBucket[i]==0 ) continue;
    pIn = pIn ? rowSetEntryMerge(pIn, aBucket[i]) : aBucket[i];
  }
  return pIn;
}

