static boolean ConvertibleRatio(int freq1, int freq2)
{
    int ratio;
    if (freq1 > freq2)
    {
        return ConvertibleRatio(freq2, freq1);
    }
    else if ((freq2 % freq1) != 0)
    {
        return false;
    }
    else
    {
        ratio = freq2 / freq1;
        while ((ratio & 1) != 0)
        {
            ratio = ratio >> 1;
        }
        return ratio == 1;
    }
}

