    {
        return;
    }
    if (field->type_info && field->type_info->kind == TYPE_ARRAY &&
        field->type_info->array_size == 0)
    {
        ASTNode *last = strct->strct.fields;
        while (last && last->next)
        {
            last = last->next;
        }
        if (last == field)
