    for (size_t i = 0; i < len; i++) {
        char c = (char)data[i];
        if (c == '\r' || c == '\n') {
            if (line_pos == 0) {
                printk("\nrt-claw> ");
                continue;
            }
            line_buf[line_pos] = '\0';
            printk("\n");
            process_line(line_buf);
            line_pos = 0;
            printk("rt-claw> ");
        } else if (c == 0x7f || c == '\b') {
            if (line_pos > 0) {
                line_pos--;
                printk("\b \b");
