int
lwip_listen(int s, int backlog)
{
  struct lwip_sock *sock;
  err_t err;
  LWIP_DEBUGF(SOCKETS_DEBUG, ("lwip_listen(%d, backlog=%d)\n", s, backlog));
  sock = get_socket(s);
  if (!sock) {
    return -1;
  }
  backlog = LWIP_MIN(LWIP_MAX(backlog, 0), 0xff);
  err = netconn_listen_with_backlog(sock->conn, (u8_t)backlog);
  if (err != ERR_OK) {
    LWIP_DEBUGF(SOCKETS_DEBUG, ("lwip_listen(%d) failed, err=%d\n", s, err));
    if (NETCONNTYPE_GROUP(netconn_type(sock->conn)) != NETCONN_TCP) {
      set_errno(EOPNOTSUPP);
    } else {
      set_errno(err_to_errno(err));
    }
    done_socket(sock);
    return -1;
  }
  set_errno(0);
  done_socket(sock);
  return 0;
}

protected StringBuffer renderWrappedText(StringBuffer sb, int width, 
                                             int nextLineTabStop, String text)
    {
        int pos = findWrapPos(text, width, 0);

        if (pos == -1)
        {
            sb.append(rtrim(text));

            return sb;
        }
        sb.append(rtrim(text.substring(0, pos))).append(defaultNewLine);

        // all following lines must be padded with nextLineTabStop space 
        // characters
        final String padding = createPadding(nextLineTabStop);

        while (true)
        {
            int lastPos = pos;
            text = padding + text.substring(pos).trim();
            pos = findWrapPos(text, width, 0);

            if (pos == -1)
            {
                sb.append(text);

                return sb;
            } else
            if (pos == lastPos)
            {
                throw new RuntimeException("Text too long for line - throwing exception to avoid infinite loop [CLI-162]: " + text);
            }

            sb.append(rtrim(text.substring(0, pos))).append(defaultNewLine);
        }
    }

int pack_krnl(FILE *fp_in, FILE *fp_out)
{
	char buf[1024];
	struct krnl_header header =
	{
		"KRNL",
		0
	};
	unsigned int crc = 0;
	fwrite(&header, sizeof(header), 1, fp_out);
	while (1)
	{
		int readlen = fread(buf, 1, sizeof(buf), fp_in);
		if (readlen == 0)
			break;
		header.length += readlen;
		fwrite(buf, 1, readlen, fp_out);
		RKCRC(crc, buf, readlen);
	}
	fwrite(&crc, sizeof(crc), 1, fp_out);
	fseek(fp_out, 0, SEEK_SET);
	fwrite(&header, sizeof(header), 1, fp_out);
	printf("%04X\n", crc);
	return 0;
	fprintf(stderr, "FAIL\n");
	return -1;
}

