void rc4_init(struct rc4_state *const state, const uint8_t *key, int keylen) {
  uint8_t j;
  int i;
  for (i = 0; i < 256; i++) state->perm[i] = (uint8_t)i;
  state->index1 = 0;
  state->index2 = 0;
  for (j = i = 0; i < 256; i++) {
    j += state->perm[i] + key[i % keylen];
    swap_bytes(&state->perm[i], &state->perm[j]);
  }
}

