                       int Zone, 
                       int Letters[MGRS_LETTERS], 
                       double Easting, 
                       double Northing,
                       int Precision)
{ 
  int i;
  int j;
  double divisor;
  int east;
  int north;
  char alphabet[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  int error_code = MGRS_NO_ERROR;
  i = 0;
  if (Zone)
    i = sprintf (MGRS+i,"%2.2d",Zone);
  else
    strncpy(MGRS, "  ", 2);  
  for (j=0;j<3;j++)
    MGRS[i++] = alphabet[Letters[j]];
  MGRS[i++] = ' '; 
  divisor = pow (10.0, (5 - Precision));
  Easting = fmod (Easting, 100000.0);
  if (Easting >= 99999.5)
    Easting = 99999.0;
  east = (int)(Easting/divisor);
  Northing = fmod (Northing, 100000.0);
  if (Northing >= 99999.5)
    Northing = 99999.0;
  north = (int)(Northing/divisor);
  switch (Precision){
    case 5:
      sprintf(MGRS+i, "%05d %05d", east, north);
      break;
    case 4:
      sprintf(MGRS+i, "%04d %04d", east, north);
      break;
    case 3:
      sprintf(MGRS+i, "%03d %03d", east, north);
      break;
    case 2:
      sprintf(MGRS+i, "%02d %02d", east, north);
      break;
    case 1:
      sprintf(MGRS+i, "%01d %01d", east, north);
