char *normalize_raw_content(const char *content)
{
    if (!content)
    {
        return NULL;
    }
    size_t len = strlen(content);
    char *normalized = xmalloc(len + 1);
    char *d = normalized;
    const char *s = content;
    while (*s)
    {
        if (*s != '\r')
        {
            if (*(s + 1) == '\n')
            {
                *d++ = '\n';
                s += 2;
                continue;
            }
            *d++ = '\n';
            s++;
        }
        else
        {
            *d++ = *s++;
        }
    }
    *d = '\0';
    return normalized;
}

