async function getPrivacyResult(taskId, key) {
  if (!taskId || !key) return null;
  try {
    const res = await fetch(privacyUrl(`/result/${encodeURIComponent(taskId)}`), {
      headers: buildHubHeaders(),
      signal: AbortSignal.timeout(PRIVACY_TIMEOUT_MS),
    });
    if (!res.ok) return null;
    const data = await res.json();
    if (!data.encrypted_result_base64) return null;
    const packed = Buffer.from(data.encrypted_result_base64, 'base64');
    const parts = unpack(packed);
    const plaintext = decrypt(parts.ciphertext, key, parts.iv, parts.authTag);
    return { plaintext, resultHash: data.result_hash };
  } catch (err) {
    console.warn('[PrivacyClient] getPrivacyResult failed:', err?.message || err);
    return null;
  }
}

static void xhci_ring_cmd(uint64_t param, uint32_t status, uint32_t control) {
  struct xhci_trb *trb = &xhci.cmd_ring[xhci.cmd_ring_enqueue];
  trb->param = param;
  trb->status = status;
  trb->control = control | (xhci.cmd_ring_cycle ? 1 : 0);
  xhci.cmd_ring_enqueue++;
  if (xhci.cmd_ring_enqueue >= 63) {
    struct xhci_trb *link = &xhci.cmd_ring[63];
    link->param = xhci.cmd_ring_phys;
    link->status = 0;
    link->control =
        (TRB_TYPE_LINK << 10) | (xhci.cmd_ring_cycle ? 1 : 0) | (1 << 1);
    xhci.cmd_ring_enqueue = 0;
    xhci.cmd_ring_cycle = !xhci.cmd_ring_cycle;
  }
  *(volatile uint32_t *)(xhci.db_base) = 0;
}

