code:
function fill_buffer_resample(gfp, outbuf, outbufPos, desired_len, inbuf, in_bufferPos, len, num_used, ch) {
        var gfc = gfp.internal_flags;
        var i, j = 0, k;
        var bpc = gfp.out_samplerate
            / gcd(gfp.out_samplerate, gfp.in_samplerate);
        if (bpc > LameInternalFlags.BPC)
            bpc = LameInternalFlags.BPC;
        var intratio = (Math.abs(gfc.resample_ratio
            - Math.floor(.5 + gfc.resample_ratio)) < .0001) ? 1 : 0;
        var fcn = 1.00 / gfc.resample_ratio;
        if (fcn > 1.00)
            fcn = 1.00;
        var filter_l = 31;
        if (0 != filter_l % 2)
            --filter_l;
        filter_l += intratio;
        var BLACKSIZE = filter_l + 1;
        if (gfc.fill_buffer_resample_init == 0) {
            gfc.inbuf_old[0] = new_float(BLACKSIZE);
            gfc.inbuf_old[1] = new_float(BLACKSIZE);
            for (i = 0; i <= 2 * bpc; ++i)
                gfc.blackfilt[i] = new_float(BLACKSIZE);
            gfc.itime[0] = 0;
            gfc.itime[1] = 0;
            for (j = 0; j <= 2 * bpc; j++) {
                var sum = 0.;
                var offset = (j - bpc) / (2. * bpc);
                for (i = 0; i <= filter_l; i++)
                    sum += gfc.blackfilt[j][i] = blackman(i - offset, fcn,
                        filter_l);
                for (i = 0; i <= filter_l; i++)
                    gfc.blackfilt[j][i] /= sum;
            }
            gfc.fill_buffer_resample_init = 1;
        }
        var inbuf_old = gfc.inbuf_old[ch];
        for (k = 0; k < desired_len; k++) {
            var time0;
            var joff;
            time0 = k * gfc.resample_ratio;
            j = 0 | Math.floor(time0 - gfc.itime[ch]);
            if ((filter_l + j - filter_l / 2) >= len)
                break;
            var offset = (time0 - gfc.itime[ch] - (j + .5 * (filter_l % 2)));
            joff = 0 | Math.floor((offset * 2 * bpc) + bpc + .5);
            var xvalue = 0.;
            for (i = 0; i <= filter_l; ++i) {
                var j2 = i + j - filter_l / 2;
                var y;
                y = (j2 < 0) ? inbuf_old[BLACKSIZE + j2] : inbuf[in_bufferPos
                + j2];
                xvalue += y * gfc.blackfilt[joff][i];
            }
            outbuf[outbufPos + k] = xvalue;
        }
        num_used.num_used = Math.min(len, filter_l + j - filter_l / 2);
        gfc.itime[ch] += num_used.num_used - k * gfc.resample_ratio;
        if (num_used.num_used >= BLACKSIZE) {
            for (i = 0; i < BLACKSIZE; i++)
                inbuf_old[i] = inbuf[in_bufferPos + num_used.num_used + i
                - BLACKSIZE];
        } else {
            var n_shift = BLACKSIZE - num_used.num_used;
            for (i = 0; i < n_shift; ++i)
                inbuf_old[i] = inbuf_old[i + num_used.num_used];
            for (j = 0; i < BLACKSIZE; ++i, ++j)
                inbuf_old[i] = inbuf[in_bufferPos + j];
        }
        return k;
    }

async function applyDesign(url, options = {}) {
  const { dir = '.', framework } = options;
  const design = await extractDesignLanguage(url, options);
  const detected = framework || detectFramework(dir);
  const applied = [];
  if (detected === 'tailwind' || detected === 'auto') {
    const twPath = findFile(dir, ['tailwind.config.js', 'tailwind.config.ts', 'tailwind.config.mjs']);
    if (twPath) {
      writeFileSync(twPath, formatTailwind(design), 'utf-8');
      applied.push({ file: twPath, type: 'tailwind' });
    }
  }
  if (detected === 'shadcn' || detected === 'auto') {
    const globalsPath = findFile(dir, [
      'app/globals.css', 'src/app/globals.css', 'styles/globals.css',
      'src/styles/globals.css', 'src/index.css', 'app/global.css',
    ]);
    if (globalsPath) {
      const existing = readFileSync(globalsPath, 'utf-8');
      const shadcnVars = formatShadcnTheme(design);
      const layerRegex = /@layer\s+base\s*\{[\s\S]*?\n\}/;
      const updated = layerRegex.test(existing)
        ? existing.replace(layerRegex, shadcnVars)
        : existing + '\n\n' + shadcnVars;
      writeFileSync(globalsPath, updated, 'utf-8');
      applied.push({ file: globalsPath, type: 'shadcn' });
    }
  }
  if (detected === 'css' || detected === 'auto') {
    const cssVarsContent = formatCssVars(design);
    const cssPath = join(dir, 'design-variables.css');
    writeFileSync(cssPath, cssVarsContent, 'utf-8');
    applied.push({ file: cssPath, type: 'css-variables' });
  }
  return { design, applied, framework: detected };
