void apply_channel_deadband(float *value, float deadband)
{
	if (deadband < 0.0001f) return; 
	if (deadband >= 0.85f) return;	
	if (fabsf(*value) < deadband) {
		*value = 0.0f;
	} else {
		if (*value <= 0.0f) {
			*value -= deadband;
		} else {
			*value += deadband;
		}
		*value /= (1 - deadband);
	}
}

