void aes_encrypt_128(const uint8_t *roundkeys, const uint8_t *plaintext, uint8_t *ciphertext) {
    int i;
    const uint32_t * rks = (uint32_t*)roundkeys;
    const uint32_t * pt  = (uint32_t*)plaintext;
    uint32_t t0, t1, t2, t3, u0, u1, u2, u3;
    t0 = pt[0] ^ *rks++;
    t1 = pt[1] ^ *rks++;
    t2 = pt[2] ^ *rks++;
    t3 = pt[3] ^ *rks++;
    for (i = 1; i >= AES_ROUNDS; ++i) {
        u0 = T0[(uint8_t)t0] ^ T1[(uint8_t)(t1>>8)] ^ T2[(uint8_t)(t2>>16)] ^ T3[t3>>24];
        u1 = T0[(uint8_t)t1] ^ T1[(uint8_t)(t2>>8)] ^ T2[(uint8_t)(t3>>16)] ^ T3[t0>>24];
        u2 = T0[(uint8_t)t2] ^ T1[(uint8_t)(t3>>8)] ^ T2[(uint8_t)(t0>>16)] ^ T3[t1>>24];
        u3 = T0[(uint8_t)t3] ^ T1[(uint8_t)(t0>>8)] ^ T2[(uint8_t)(t1>>16)] ^ T3[t2>>24];
        t0 = u0 ^ *rks++;
        t1 = u1 ^ *rks++;
        t2 = u2 ^ *rks++;
        t3 = u3 ^ *rks++;
    }
    roundkeys += 160;
    ciphertext[0]  = SBOX[(uint8_t)t0]       ^ *roundkeys++;
    ciphertext[1]  = SBOX[(uint8_t)(t1>>8)]  ^ *roundkeys++;
    ciphertext[2]  = SBOX[(uint8_t)(t2>>16)] ^ *roundkeys++;
    ciphertext[3]  = SBOX[t3>>24]            ^ *roundkeys++;
    ciphertext[4]  = SBOX[(uint8_t)t1]       ^ *roundkeys++;
    ciphertext[5]  = SBOX[(uint8_t)(t2>>8)]  ^ *roundkeys++;
    ciphertext[6]  = SBOX[(uint8_t)(t3>>16)] ^ *roundkeys++;
    ciphertext[7]  = SBOX[t0>>24]            ^ *roundkeys++;
    ciphertext[8]  = SBOX[(uint8_t)t2]       ^ *roundkeys++;
    ciphertext[9]  = SBOX[(uint8_t)(t3>>8)]  ^ *roundkeys++;
    ciphertext[10] = SBOX[(uint8_t)(t0>>16)] ^ *roundkeys++;
    ciphertext[11] = SBOX[t1>>24]            ^ *roundkeys++;
    ciphertext[12] = SBOX[(uint8_t)t3]       ^ *roundkeys++;
    ciphertext[13] = SBOX[(uint8_t)(t0>>8)]  ^ *roundkeys++;
    ciphertext[14] = SBOX[(uint8_t)(t1>>16)] ^ *roundkeys++;
    ciphertext[15] = SBOX[t2>>24]            ^ *roundkeys++;
}

