    if (!facts)
    {
        load_facts();
        if (!facts)
        {
            return;
        }
    }
    int matches[10];
    int match_count = 0;
    for (int i = 0; i < fact_count; i++)
    {
        if (TRIGGER_GLOBAL != facts[i].trigger)
        {
            matches[match_count++] = i;
            if (match_count >= 10)
            {
                break;
            }
        }
    }
    if (0 == match_count)
    {
        return;
