    pool_chunk *prev = NULL, *next = ctx->free_list;
    while (next && next < cur) {
        prev = next;
        next = next->next;
    }
    if (prev) prev->next = cur;
    else ctx->free_list = cur;
    cur->next = next;
    if (next && ((u8 *)cur + cur->size) == (u8 *)next) {
        cur->size += next->size;
        cur->next = next->next;
    }
    if (prev && ((u8 *)prev + prev->size) == (u8 *)cur) {
        prev->size += cur->size;
        prev->next = cur->next;
    }
}

